// ===========================================================================
// v0.84.0-c11.9 checkpoint 80 — CLASS 11 CHAPTER 3, TRIGONOMETRIC FUNCTIONS.
//
// Every angle in these lessons carries its unit, every trigonometric value is
// read from `circularFunctions`, every quadrant sign is computed from the
// coordinates, and every graph sample is generated by the function with its
// branches broken at the undefined arguments. Nothing is typed twice.
//
// Class 10's `specialAngles` is untouched. The two models agree on all
// eighteen acute standard values, which a compatibility test proves.
// ===========================================================================

import type { AuthoredSection } from './authoredSection';
import { type L, makeLesson } from './class11Lesson';
import {
  degrees, formatAngle, isCoterminal, piMultiple, principal, sense, toDegree, toRadian,
} from './angleMeasure';
import {
  CIRCULAR_FUNCTIONS, buildGraph, generalSolution, quadrantOf, signsInQuadrant,
  solutionFamilyChecks, unitCirclePoint, valueAt, writtenValue, formatSigned,
} from './circularFunctions';

export const TRIG_C11_CHAPTER_ID = 'ncert_kemh1_ch03';
const BOOK = 'Mathematics, Textbook for Class XI (NCERT, Reprint 2026-27)';
const SRC = 'kemh1';
const INSPECTED = '2026-10-26';

const source = (sec: string, title: string, page: number) => {
  // A subsection such as 3.2.1 is taught by this lesson, but the official
  // registry holds sections, so the parent is named and the subsection
  // recorded beside it rather than a section id being fabricated.
  const parts = sec.split('.');
  const parent = parts.length > 2 ? parts.slice(0, 2).join('.') : sec;
  return {
  officialChapterId: TRIG_C11_CHAPTER_ID,
  officialSectionId: `ncert_kemh1_s${parent.replace(/\./g, '_')}`,
  ...(parts.length > 2 ? { officialSubsectionNumber: sec } : {}),
  sectionNumber: parent, exactTitle: title, startPage: page,
  textbook: BOOK, sourceReference: SRC, inspectionDate: INSPECTED,
  };
};

/**
 * FO-3 has no NCERT owner: the current kemh1 teaches no general solution of a
 * trigonometric equation. The `cbse_only` kind introduced at checkpoint 79
 * carries that truthfully — a CBSE entry, no official section id, and a
 * chapter used for navigation rather than ownership.
 */
const cbseSource = (title: string, page: number, entry: string) => ({
  officialChapterId: TRIG_C11_CHAPTER_ID,
  sourceKind: 'cbse_only' as const,
  cbseEntryId: entry,
  // Empty, following the path `source_segment` established: a lesson with no
  // official section names none rather than borrowing one.
  officialSectionId: '',
  sectionNumber: '', exactTitle: title, startPage: page,
  textbook: 'Mathematics, Subject Code 041, Classes XI-XII, CBSE 2026-27',
  sourceReference: 'Maths_SecP2_2026-27', inspectionDate: INSPECTED,
});

const lesson = (l: L): AuthoredSection => makeLesson(l, source, undefined, cbseSource);

// --- values derived once, read by the prose -------------------------------
const v = (d: number, n: 'sin' | 'cos' | 'tan' | 'cosec' | 'sec' | 'cot') =>
  writtenValue(valueAt(degrees(d), n));
const pt = (d: number) => {
  const p = unitCirclePoint(degrees(d));
  return `(${formatSigned(p.x)}, ${formatSigned(p.y)})`;
};
const Q = (q: 1 | 2 | 3 | 4) => signsInQuadrant(q);

export const G_SIN = buildGraph('g_sin', 'sin', -2 * Math.PI, 2 * Math.PI,
  'The graph of sin over two full turns, from minus two pi to two pi. One unbroken wave crossing zero at every multiple of pi, rising to 1 and falling to minus 1, so the whole curve lies between those two values.');
export const G_COS = buildGraph('g_cos', 'cos', -2 * Math.PI, 2 * Math.PI,
  'The graph of cos over two full turns. One unbroken wave of the same shape as sin but starting at 1 when the argument is zero, again lying entirely between minus 1 and 1.');
export const G_TAN = buildGraph('g_tan', 'tan', -Math.PI, Math.PI,
  'The graph of tan from minus pi to pi, drawn in three separate branches. The curve is broken at minus pi by two and at pi by two, where cos is zero and tan has no value; each branch rises steeply away from those arguments and the values are not bounded above or below.');
export const CANONICAL_GRAPHS = [G_SIN, G_COS, G_TAN];

